    Bug 2013486 - Wait for search attribute menupopup to hide before opening Custom Headers dialog. r=mkmelin

    Opening a modal dialog while a menupopup is in the 'hiding' state can cause
    focus issues and UI hangs. This change makes onSelect async and awaits the
    `popuphidden` event to ensure the pointer capture is released before the
    dialog opens.

    Differential Revision: https://phabricator.services.mozilla.com/D281162

diff --git a/mailnews/search/content/searchWidgets.js b/mailnews/search/content/searchWidgets.js
index a69400eb57f..97567bff53d 100644
--- a/mailnews/search/content/searchWidgets.js
+++ b/mailnews/search/content/searchWidgets.js
@@ -469,8 +469,18 @@
       this.menulist.selectedItem = this.validMenuitem;
     }

-    onSelect() {
+    async onSelect() {
       if (this.menulist.value == Ci.nsMsgSearchAttrib.OtherHeader) {
+        // Wait for the menupopup to finish closing to have the pointer capture
+        // released before opening the modal dialog.
+        if (this.menupopup.state != "closed") {
+          await new Promise(resolve => {
+            this.menupopup.addEventListener("popuphidden", resolve, {
+              once: true,
+            });
+          });
+        }
+
         // Customize menuitem selected.
         const args = {};
         window.openDialog(
